package org.circus.core;

/** Layout from the Unity native StateBacklog, using the game's current work1 atlas. */
final class Dc3rBacklog {
    private static Dc3rHost.Quad quad(int x,int y,int sx,int sy,int w,int h){Dc3rHost.Quad q=new Dc3rHost.Quad();q.work="work1";q.x=x;q.y=y;q.sx=sx;q.sy=sy;q.width=w;q.height=h;return q;}
    private static Dc3rHost.Button button(String label,int x,int y,int w,int h,int sx,int sy,int delta){Dc3rHost.Button b=new Dc3rHost.Button();b.action=label;b.left=x;b.top=y;b.right=x+w;b.bottom=y+h;b.normal.add(quad(x,y,sx,sy,w,h));b.hover.add(quad(x,y,sx,sy+delta,w,h));b.pressed.add(quad(x,y,sx,sy+delta*2,w,h));return b;}
    private static Dc3rHost.Text text(int x,int y,int width,String value,int color){Dc3rHost.Text t=new Dc3rHost.Text();t.x=x;t.y=y;t.width=width;t.leading=28;t.text=value;t.color=color;return t;}
    private static int icon(String name,boolean dc2){name=name.replace("的声音","");String[] names=dc2?new String[]{"音姬","由梦","茜","杏","艾莉卡","小恋","麻耶","美夏","真由纪","奈奈香","杉并","樱","涉","义之"}:new String[]{"葵","莎拉|纱罗","姬乃","立夏|莉卡","夏露露","杉并","伊丽莎白","吉尔","伊恩","耕助","玛丽","美琴","美夏","瑠璃香","樱","巴","爱德华","夕阳","柚","清隆","艾德","四季"};for(int i=0;i<names.length;i++)for(String n:names[i].split("\\|"))if(n.equals(name))return i+(dc2?22:0);return -1;}
    static void build(Dc3rHost h){Dc3rHost.Panel p=new Dc3rHost.Panel();int count=Math.min(4,h.history.size()),max=Math.max(0,h.history.size()-4);h.backlogPosition=Math.max(0,Math.min(max,h.backlogPosition));for(int i=0;i<count;i++){Dc3rHost.History entry=h.history.get(h.backlogPosition+i);int y=24+i*134;p.quads.add(quad(200,y,228,0,678,122));Dc3rHost.Button b=new Dc3rHost.Button();b.left=200;b.top=y;b.right=878;b.bottom=y+122;b.action=entry.voice.isEmpty()?"-":":history"+i;if(!entry.voice.isEmpty())p.quads.add(quad(207,y+6,83,118,26,26));int color=h.colors.getOrDefault(15,0xff202030);b.normalText.add(text(364,y+12,500,entry.text,color));b.hoverText.add(text(364,y+12,500,entry.text,0xffffffff));if(!entry.name.isEmpty()){int icon=icon(entry.name,h.readFlag((101<<16)+106)==1);if(icon>=0)p.quads.add(quad(232,y+4,167+(icon%6)*116,132+(icon/6)*116,116,116));else{b.normalText.add(text(242,y+12,116,entry.name,color));b.hoverText.add(text(242,y+12,116,entry.name,0xffffffff));}}p.buttons.add(b);}
        p.buttons.add(button(":endlog",934,503,82,68,0,0,68));if(h.canRewindHistory(h.backlogPosition))p.buttons.add(button(":logjump",24,72,162,48,0,205,48));
        if(h.backlogPosition>0)p.buttons.add(button(":logpageup",115,140,72,36,155,1,40));if(h.backlogPosition<max)p.buttons.add(button(":logpagedown",115,510,72,36,83,1,40));p.buttons.add(button(":loglineup",948,85,41,23,906,0,24));p.buttons.add(button(":loglinedown",949,444,41,23,947,0,24));p.quads.add(quad(954,110,988,0,32,332));if(max>0){p.quads.add(quad(954,112+(int)Math.round(300.0*h.backlogPosition/max),908,74,30,30));Dc3rHost.Button b=new Dc3rHost.Button();b.left=954;b.top=110;b.right=986;b.bottom=442;b.action=":backlogslider";b.sliderVertical=true;b.sliderStart=126;b.sliderEnd=426;b.sliderSteps=max+1;b.sliderFlag=(101<<16)+107;p.buttons.add(b);}h.menu=p;h.hovered=h.pressed=-1;
    }
}
